import time


class TTLCache:
    def __init__(self, default_ttl, clock=time.monotonic):
        self._default_ttl = default_ttl
        self._clock = clock
        self._entries = {}                      # key -> (value, moment it expires)

    def set(self, key, value, ttl=None):
        if ttl is None:                         # not "ttl or default": 0 is a real ttl
            ttl = self._default_ttl
        self._entries[key] = (value, self._clock() + ttl)

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if self._clock() >= expires_at:
            del self._entries[key]              # delete it now so dead entries do not pile up
            return None
        return value

    def __len__(self):
        now = self._clock()
        dead = [key for key, (_, expires_at) in self._entries.items() if expires_at <= now]
        for key in dead:
            del self._entries[key]
        return len(self._entries)
